python
def expandingPanelsFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    left=0
    s=0
    for right,x in enumerate(a):
        s+=x
        while left<=right and s-a[left]>=k:
            s-=a[left]
            left+=1
        out.append(right-left+1 if s>=k else 0)
    return next((x for x in out if x>=k),-1)


java
class Solution {
  public int expandingPanelsFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int l=0,s=0;for(int r=0;r<a.length;r++){s+=a[r];while(l<=r&&s-a[l]>=k)s-=a[l++];out.add(s>=k?r-l+1:0);}}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
